using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using Unity.CodeEditor;
using UnityEditor;
using UnityEngine;

namespace Haze.Ide.Editor
{
    /// <summary>
    /// Haze as an External Script Editor: Unity asks it to keep the .sln and
    /// .csproj files up to date and to open scripts at a line.
    /// </summary>
    [InitializeOnLoad]
    public class HazeCodeEditor : IExternalCodeEditor
    {
        static HazeCodeEditor()
        {
            CodeEditor.Register(new HazeCodeEditor());
            // Project files are generated by the selected editor only. Sync
            // after every domain reload: a new build target, scripting define
            // or compiler option recompiles the scripts without touching any
            // file Unity reports to SyncIfNeeded. Unchanged files are not rewritten.
            if (Discovery.IsHaze(CodeEditor.CurrentEditorInstallation) && !Application.isBatchMode && !AssetDatabase.IsAssetImportWorkerProcess())
            {
                EditorApplication.delayCall += ProjectGeneration.Sync;
                HazeLink.Start();
            }
        }

        public CodeEditor.Installation[] Installations =>
            Discovery.Find().Select(p => new CodeEditor.Installation { Name = "Haze", Path = p }).ToArray();

        public bool TryGetInstallationForPath(string editorPath, out CodeEditor.Installation installation)
        {
            installation = default;
            if (!Discovery.IsHaze(editorPath)) return false;
            installation = new CodeEditor.Installation { Name = "Haze", Path = editorPath };
            return true;
        }

        static GUIStyle s_Link;

        public void OnGUI()
        {
            GUILayout.BeginHorizontal();
            const string text = "Customize handled extensions in";
            EditorGUILayout.LabelField(text, GUILayout.Width(EditorStyles.label.CalcSize(new GUIContent(text)).x));
            if (Link("Project Settings | Editor | Additional extensions to include"))
                SettingsService.OpenProjectSettings("Project/Editor");
            GUILayout.EndHorizontal();

            EditorGUILayout.LabelField("Generate .csproj files for:");
            EditorGUI.indentLevel++;
            Toggle(GenerationFlags.Embedded, "Embedded packages", "");
            Toggle(GenerationFlags.Local, "Local packages", "");
            Toggle(GenerationFlags.Registry, "Registry packages", "");
            Toggle(GenerationFlags.Git, "Git packages", "");
            Toggle(GenerationFlags.BuiltIn, "Built-in packages", "");
            Toggle(GenerationFlags.LocalTarball, "Local tarball", "");
            Toggle(GenerationFlags.Unknown, "Packages from unknown sources", "");
            Toggle(GenerationFlags.PlayerProjects, "Player projects",
                "For each player assembly generate an additional 'Name.Player.csproj', compiled without UNITY_EDITOR.");
            Toggle(GenerationFlags.UnityAnalyzers, "Microsoft.Unity.Analyzers",
                "Add Unity's Roslyn analyzers and suppressors to the generated projects (Haze only; Unity's compilation is unchanged).");
            var rect = EditorGUI.IndentedRect(EditorGUILayout.GetControlRect());
            rect.width = 252;
            if (GUI.Button(rect, "Regenerate project files")) SyncAll();
            EditorGUI.indentLevel--;
        }

        static void Toggle(GenerationFlags flag, string label, string tooltip)
        {
            var flags = Settings.Flags;
            var on = flags.HasFlag(flag);
            if (EditorGUILayout.Toggle(new GUIContent(label, tooltip), on) == on) return;
            Settings.Flags = flags ^ flag;
            ProjectGeneration.Sync();
        }

        static bool Link(string text)
        {
            if (s_Link == null)
            {
                var color = EditorGUIUtility.isProSkin ? new Color(0.30f, 0.56f, 0.98f) : new Color(0.05f, 0.33f, 0.80f);
                s_Link = new GUIStyle(EditorStyles.label) { normal = { textColor = color }, hover = { textColor = color } };
            }
            var content = new GUIContent(text);
            var rect = GUILayoutUtility.GetRect(content, s_Link, GUILayout.ExpandWidth(false));
            EditorGUIUtility.AddCursorRect(rect, MouseCursor.Link);
            return GUI.Button(rect, content, s_Link);
        }

        public void SyncIfNeeded(string[] addedFiles, string[] deletedFiles, string[] movedFiles, string[] movedFromFiles, string[] importedFiles)
        {
            var changed = addedFiles.Concat(deletedFiles).Concat(movedFiles).Concat(movedFromFiles).Concat(importedFiles);
            if (ProjectGeneration.Affects(changed)) ProjectGeneration.Sync();
        }

        public void SyncAll() => ProjectGeneration.Sync();

        /// <summary>Haze picked as External Script Editor: listen for it right away, not after the next reload.</summary>
        public void Initialize(string editorInstallationPath)
        {
            if (Discovery.IsHaze(editorInstallationPath)) HazeLink.Start();
        }

        public bool OpenProject(string filePath = "", int line = -1, int column = -1)
        {
            // Unity asks the code editor first for every asset opened; false
            // lets it open the rest itself (a .prefab in Prefab Mode, a scene...).
            if (!string.IsNullOrEmpty(filePath) && !IsHandled(filePath)) return false;
            var exe = Discovery.Executable(CodeEditor.CurrentEditorInstallation);
            if (exe == null) return false;
            if (!File.Exists(ProjectGeneration.SolutionPath)) ProjectGeneration.Sync();

            var args = new List<string> { ProjectGeneration.ProjectDirectory };
            if (!string.IsNullOrEmpty(filePath))
            {
                args.Add(ProjectGeneration.Resolve(filePath));
                if (line > 0) args.AddRange(new[] { "--line", line.ToString() });
                if (column > 0) args.AddRange(new[] { "--column", column.ToString() });
            }
            // A running Haze receives the request and focuses its window.
            Process.Start(new ProcessStartInfo
            {
                FileName = exe,
                Arguments = string.Join(" ", args.Select(Quote)),
                UseShellExecute = false,
                CreateNoWindow = true,
            });
            return true;
        }

        static readonly string[] k_Always = { "asmdef", "asmref", "rsp", "additionalfile" };

        /// <summary>Unity's built-in script extensions, those added in Project Settings | Editor, and the files that shape compilation.</summary>
        static bool IsHandled(string path)
        {
            var ext = Path.GetExtension(path).TrimStart('.').ToLowerInvariant();
            return ext.Length > 0 && (k_Always.Contains(ext)
                || EditorSettings.projectGenerationBuiltinExtensions.Any(e => e.TrimStart('.').ToLowerInvariant() == ext)
                || EditorSettings.projectGenerationUserExtensions.Any(e => e.TrimStart('.').ToLowerInvariant() == ext));
        }

        static string Quote(string arg) => "\"" + arg.Replace("\"", "\\\"") + "\"";
    }
}
